def main():
    target=base.SITE/'ru'; target.mkdir(exist_ok=True)
    for page,(title,lead) in RU.items():
        (target/page).write_text(base.page_html('ru',page,title,lead),encoding='utf-8')
    print(f'Built native Russian migration-route translations: {len(RU)} pages')

if __name__=='__main__': main()
